    }
    pub fn append_group(
        &mut self,
        scene: SceneId,
        value: OpacityGroup,
        control: &mut dyn WorkControl,
    ) -> Result<GroupId> {
        let i = self.writable(scene)?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::group(self, scene, &value, self.scenes[i].groups.len(), control)?;
        if self.scenes[i].groups.len() >= self.limits.groups {
            return Err(limit(LimitKind::Nodes));
        }
        let nested = 0;
        self.pending(nested)?;
        let serial = self.serial()?;
        room!(self, i, groups, 1, self.limits.groups, nested);
        room!(self, i, groups_serials, 1, self.limits.groups, nested);
        control.checkpoint().map_err(stopped)?;
        self.retain(nested)?;
        let id = GroupId {
            owner: self.owner,
            scene: scene.slot,
            slot: self.scenes[i].groups.len() as u32,
            serial,
        };
        self.scenes[i].groups.push(value);
        self.scenes[i].groups_serials.push(serial);
        Ok(id)
    }
    pub fn append_image(
        &mut self,
        scene: SceneId,
        value: Image,
        control: &mut dyn WorkControl,
    ) -> Result<usize> {
        let i = self.writable(scene)?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::image(&value, control)?;
        let pixels = self.scenes[i].image_pixels;
        if add(
            pixels,
            (value.pixels.width as usize) * (value.pixels.height as usize),
        )? > 67_108_864
        {
            return Err(limit(LimitKind::Images));
        }
        let nested = bytes(&value.pixels.rgba)?;
        self.pending(nested)?;
        room!(self, i, images, 1, self.limits.shapes, nested);
        control.checkpoint().map_err(stopped)?;
        self.retain(nested)?;
        let index = self.scenes[i].images.len();
        self.scenes[i].image_pixels = add(
            pixels,
            (value.pixels.width as usize) * (value.pixels.height as usize),
        )?;
        self.scenes[i].images.push(value);
        Ok(index)
    }
    pub fn append_stops(
        &mut self,
        scene: SceneId,
        values: &[PaintStop],
        control: &mut dyn WorkControl,
    ) -> Result<TableRange> {
        let i = self.writable(scene)?;
        control.checkpoint().map_err(stopped)?;
        if values.len() > 256 {
            return Err(limit(LimitKind::PaintStops));
        }
        crate::validate::stops(values, control)?;
        let cap = self.limits.stops;
        if add(self.scenes[i].stops.len(), values.len())? > cap {
            return Err(limit(LimitKind::PaintStops));
        }
        room!(self, i, stops, values.len(), cap, 0);
        let mark = self.checkpoint_internal(scene)?;
        let first = self.scenes[i].stops.len();
        for value in values {
            if let Err(stop) = control.charge(WorkKind::PaintVisit, 1) {
                self.rollback_internal(mark)?;
                return Err(stopped(stop));
            }
            self.scenes[i].stops.push(*value);
        }
        Ok(TableRange {
            first,
            count: values.len(),
        })
    }
    pub fn append_dashes(
        &mut self,
        scene: SceneId,
        values: &[f64],
        control: &mut dyn WorkControl,
    ) -> Result<TableRange> {
        let i = self.writable(scene)?;
        control.checkpoint().map_err(stopped)?;
        if values.len() > 16 {
            return Err(limit(LimitKind::DashCache));
        }
        for value in values {
            control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
            if !value.is_finite() || *value < 0.0 || *value > 1e6 {
                return Err(invalid(0));
            }
        }
        let cap = self
            .limits
            .shapes
            .checked_mul(16)
            .ok_or_else(crate::memory::arithmetic)?;
        room!(self, i, dash_values, values.len(), cap, 0);
        let mark = self.checkpoint_internal(scene)?;
        let first = self.scenes[i].dash_values.len();
        for value in values {
            if let Err(stop) = control.charge(WorkKind::StrokeTest, 1) {
                self.rollback_internal(mark)?;
                return Err(stopped(stop));
            }
            self.scenes[i].dash_values.push(*value);
        }
        Ok(TableRange {
            first,
            count: values.len(),
        })
    }
    pub fn append_fill_paint(
        &mut self,
        scene: SceneId,
        value: Paint,
        control: &mut dyn WorkControl,
    ) -> Result<usize> {
        let i = self.writable(scene)?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::paint(self, scene, &value, control)?;
        room!(self, i, fill_paints, 1, self.limits.shapes, 0);
        control.checkpoint().map_err(stopped)?;
        let index = self.scenes[i].fill_paints.len();
        self.scenes[i].fill_paints.push(value);
        Ok(index)
    }
    pub fn append_stroke_paint(
        &mut self,
        scene: SceneId,
        value: Paint,
        control: &mut dyn WorkControl,
    ) -> Result<usize> {
        let i = self.writable(scene)?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::paint(self, scene, &value, control)?;
        room!(self, i, stroke_paints, 1, self.limits.shapes, 0);
        control.checkpoint().map_err(stopped)?;
        let index = self.scenes[i].stroke_paints.len();
        self.scenes[i].stroke_paints.push(value);
        Ok(index)
    }
    pub fn append_filter(
        &mut self,
        scene: SceneId,
        mut value: Filter,
        primitives: &[FilterPrimitive],
        control: &mut dyn WorkControl,
    ) -> Result<FilterId> {
        let i = self.writable(scene)?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::filter(value, primitives, control)?;
        for p in primitives {
            if p.source_offset > self.source.len() {
                return Err(invalid(p.source_offset));
            }
        }
        if self.scenes[i].filters.len() >= self.limits.filters {
            return Err(limit(LimitKind::Filters));
        }
        let serial = self.serial()?;
        room!(self, i, filters, 1, self.limits.filters, 0);
        room!(self, i, filters_serials, 1, self.limits.filters, 0);
        room!(self, i, filter_primitives, primitives.len(), 65536, 0);
        let mark = self.checkpoint_internal(scene)?;
        value.primitives = TableRange {
            first: self.scenes[i].filter_primitives.len(),
            count: primitives.len(),
        };
        for primitive in primitives {
            if let Err(stop) = control.charge(WorkKind::FilterPixel, 1) {
                self.rollback_internal(mark)?;
                return Err(stopped(stop));
            }
            self.scenes[i].filter_primitives.push(*primitive);
        }
        let id = FilterId {
            owner: self.owner,
            scene: scene.slot,
            slot: self.scenes[i].filters.len() as u32,
            serial,
        };
        self.scenes[i].filters.push(value);
        self.scenes[i].filters_serials.push(serial);
        Ok(id)
    }
}
use crate::builder::room;
use crate::memory::{add, bytes};
use crate::types::{invalid, limit, stopped};
use crate::*;
impl SceneBuilder {
    pub fn append_shape(
        &mut self,
        scene: SceneId,
        input: ShapeInput,
        control: &mut dyn WorkControl,
    ) -> Result<ShapeId> {
        let i = self.writable(scene)?;
        control.checkpoint().map_err(stopped)?;
        if input.path.edges.len() != input.edge_colors.len() {
            return Err(invalid(0));
        }
        crate::validate::shape_attributes(self, scene, &input.shape, control)?;
        crate::validate::path(&self.source, &input.path, control)?;
        let s = &self.scenes[i];
        for (len, extra, cap, kind) in [
            (s.shapes.len(), 1, self.limits.shapes, LimitKind::Shapes),
            (
                s.edges.len(),
                input.path.edges.len(),
                self.limits.edges,
                LimitKind::Edges,
            ),
            (
                s.path_segments.len(),
                input.path.segments.len(),
                self.limits.commands,
                LimitKind::PathCommands,
            ),
            (
                s.path_numbers.len(),
                input.path.numbers.len(),
                self.limits.numbers,
                LimitKind::PathNumbers,
            ),
        ] {
            if add(len, extra)? > cap {
                return Err(limit(kind));
            }
        }
        let pending = add(
            add(
                add(bytes(&input.path.edges)?, bytes(&input.path.subpaths)?)?,
                add(bytes(&input.path.segments)?, bytes(&input.path.numbers)?)?,
            )?,
            bytes(&input.edge_colors)?,
        )?;
        self.pending(pending)?;
        let serial = self.serial()?;
        room!(self, i, shapes, 1, self.limits.shapes, pending);
        room!(self, i, shapes_serials, 1, self.limits.shapes, pending);
        room!(
            self,
            i,
            edges,
            input.path.edges.len(),
            self.limits.edges,
            pending
        );
        room!(
            self,
            i,
            edge_colors,
            input.edge_colors.len(),
            self.limits.edges,
            pending
        );
        room!(
            self,
            i,
            edge_shape_ids,
            input.path.edges.len(),
            self.limits.edges,
            pending
        );
        room!(
            self,
            i,
            path_subpaths,
            input.path.subpaths.len(),
            self.limits.commands,
            pending
        );
        room!(
            self,
            i,
            path_segments,
            input.path.segments.len(),
            self.limits.commands,
            pending
        );
        room!(
            self,
            i,
            path_numbers,
            input.path.numbers.len(),
            self.limits.numbers,
            pending
        );
        let mark = self.checkpoint_internal(scene)?;
        let id = ShapeId {
            owner: self.owner,
            scene: scene.slot,
            slot: self.scenes[i].shapes.len() as u32,
            serial,
        };
        let result = self.publish_shape(i, id, input, control);
        if result.is_err() {
            self.rollback_internal(mark)?;
        }
        result.map(|()| id)
    }
    fn publish_shape(
        &mut self,
        i: usize,
        id: ShapeId,
        input: ShapeInput,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let scene = &mut self.scenes[i];
        let edge_first = scene.edges.len();
        let number_first = scene.path_numbers.len();
        let mut shape = input.shape;
        shape.edges = TableRange {
            first: edge_first,
            count: input.path.edges.len(),
        };
        shape.subpaths = TableRange {
            first: scene.path_subpaths.len(),
            count: input.path.subpaths.len(),
        };
        for (edge, color) in input.path.edges.into_iter().zip(input.edge_colors) {
            control.charge(WorkKind::Edge, 1).map_err(stopped)?;
            scene.edges.push(edge);
            scene.edge_colors.push(color);
            scene.edge_shape_ids.push(id.slot);
        }
        for mut subpath in input.path.subpaths {
            control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
            subpath.first_edge = add(subpath.first_edge, edge_first)?;
            scene.path_subpaths.push(subpath);
        }
        for mut path in input.path.segments {
            control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
            path.first_edge = add(path.first_edge, edge_first)?;
            path.first_number = add(path.first_number, number_first)?;
            scene
                .path_segments
                .push(ScenePathSegment { path, shape: id });
        }
        for number in input.path.numbers {
            control.charge(WorkKind::SourceRead, 1).map_err(stopped)?;
            scene.path_numbers.push(number);
        }
        control.checkpoint().map_err(stopped)?;
        scene.shapes.push(shape);
        scene.shapes_serials.push(id.serial);
        Ok(())
    }
}

use crate::types::{invalid, limit, stopped};
use crate::*;
use vexel_geometry::affine_valid;
pub(crate) fn charge(control: &mut dyn WorkControl, kind: WorkKind) -> Result<()> {
    control.charge(kind, 1).map_err(stopped)
}
fn finite(values: &[f64]) -> bool {
    values.iter().all(|v| v.is_finite())
}
fn coord(value: f64) -> bool {
    value.is_finite() && value.abs() <= 1e6
}
fn region(values: &[f64; 4]) -> bool {
    finite(values) && values.iter().all(|v| v.abs() <= 1e6) && values[2] >= 0.0 && values[3] >= 0.0
}
fn span(source: &[u8], value: Span) -> Result<()> {
    if value.slice(source).is_none() {
        Err(invalid(value.start))
    } else {
        Ok(())
    }
}
fn source_offset(source: &[u8], offset: usize) -> Result<()> {
    if offset > source.len() {
        Err(invalid(offset))
    } else {
        Ok(())
    }
}
fn edge(value: Edge) -> Result<()> {
    if [value.a.x, value.a.y, value.b.x, value.b.y]
        .into_iter()
        .all(coord)
    {
        Ok(())
    } else {
        Err(invalid(0))
    }
}
pub(crate) fn viewport(value: Viewport) -> Result<()> {
    if value.width == 0
        || value.height == 0
        || !coord(value.view_x)
        || !coord(value.view_y)
        || !coord(value.view_width)
        || !coord(value.view_height)
        || value.view_width <= 0.0
        || value.view_height <= 0.0
        || !finite(&[value.aspect.align_x, value.aspect.align_y])
        || !(0.0..=1.0).contains(&value.aspect.align_x)
        || !(0.0..=1.0).contains(&value.aspect.align_y)
    {
        Err(Diagnostic {
            kind: ErrorKind::Viewport,
            offset: 0,
        })
    } else {
        Ok(())
    }
}
pub(crate) fn transform(
    builder: &SceneBuilder,
    id: SceneId,
    value: &TransformFrame,
    control: &mut dyn WorkControl,
) -> Result<()> {
    charge(control, WorkKind::Transform)?;
    source_offset(&builder.source, value.source_offset)?;
    if ![value.attribute, value.suffix, value.motion]
        .into_iter()
        .all(affine_valid)
    {
        return Err(invalid(value.source_offset));
    }
    if let Some(parent) = value.parent {
        if builder.scene(id)?.transform(parent).is_none() {
            return Err(invalid(value.source_offset));
        }
    }
    Ok(())
}
pub(crate) fn stops(values: &[PaintStop], control: &mut dyn WorkControl) -> Result<()> {
    let mut previous = 0.0;
    for stop in values {
        charge(control, WorkKind::PaintVisit)?;
        if !stop.offset.is_finite() || stop.offset < previous || stop.offset > 1.0 {
            return Err(invalid(0));
        }
        previous = stop.offset;
    }
    Ok(())
}
pub(crate) fn paint(
    builder: &SceneBuilder,
    id: SceneId,
    value: &Paint,
    control: &mut dyn WorkControl,
) -> Result<()> {
    paint_view(builder.scene(id)?, value, control)
}
pub(crate) fn paint_view(
    scene: SceneView<'_>,
    value: &Paint,
    control: &mut dyn WorkControl,
) -> Result<()> {
    charge(control, WorkKind::PaintVisit)?;
    value.stops.require(scene.stops.len(), 0)?;
    if value.stops.count > 256 {
        return Err(limit(LimitKind::PaintStops));
    }
    stops(
        value.stops.slice(scene.stops).ok_or_else(|| invalid(0))?,
        control,
    )?;
    if !finite(&value.coordinates)
        || !region(&value.bounds)
        || ![
            value.user_inverse,
            value.gradient_inverse,
            value.pattern_inverse,
        ]
        .into_iter()
        .all(affine_valid)
        || !value.pattern_opacity.is_finite()
        || !(0.0..=1.0).contains(&value.pattern_opacity)
    {
        return Err(invalid(0));
    }
    if value.coordinates.iter().any(|v| v.abs() > 1e6) {
        return Err(invalid(0));
    }
    if value.kind == PaintKind::Radial && value.coordinates[2] < 0.0 {
        return Err(invalid(0));
    }
    if let Some(pattern) = value.pattern {
        if scene.pattern(pattern).is_none() {
            return Err(invalid(0));
        }
    }
    if value.kind == PaintKind::Pattern && value.pattern.is_none() {
        return Err(invalid(0));
    }
    Ok(())
}
pub(crate) fn shape_attributes(
    builder: &SceneBuilder,
    id: SceneId,
    value: &Shape,
    control: &mut dyn WorkControl,
) -> Result<()> {
    shape_attributes_view(builder.scene(id)?, value, control)
}
pub(crate) fn shape_attributes_view(
    scene: SceneView<'_>,
    value: &Shape,
    control: &mut dyn WorkControl,
) -> Result<()> {
    charge(control, WorkKind::TokenVisit)?;
    span(scene.source(), value.source.element)?;
    if !affine_valid(value.source.transform) || !affine_valid(value.stroke_inverse) {
        return Err(invalid(value.source.element.start));
    }
    if let Some(node) = value.source.transform_node {
        if scene.transform(node).is_none() {
            return Err(invalid(0));
        }
    }
    if let Some(clip) = value.clip {
        if scene.clip(clip).is_none() {
            return Err(invalid(0));
        }
    }
    for (index, length) in [
        (value.fill_paint, scene.fill_paints.len()),
        (value.stroke_paint, scene.stroke_paints.len()),
        (value.image, scene.images.len()),
    ] {
        if index.is_some_and(|i| i >= length) {
            return Err(invalid(0));
        }
    }
    let stroke = value.stroke;
    if !stroke.width.is_finite()
        || !(0.0..=1024.0).contains(&stroke.width)
        || !stroke.miter_limit.is_finite()
        || !(1.0..=64.0).contains(&stroke.miter_limit)
        || !coord(stroke.dash_offset)
        || stroke.paint_order > 5
    {
        return Err(invalid(0));
    }
    stroke.dash_values.require(scene.dash_values.len(), 0)?;
    if stroke.dash_values.count > 16 {
        return Err(limit(LimitKind::DashCache));
    }
    Ok(())
}
pub(crate) fn path(
    source: &[u8],
    value: &vexel_svg_path::PathDocument,
    control: &mut dyn WorkControl,
) -> Result<()> {
    for &e in &value.edges {
        charge(control, WorkKind::Edge)?;
        edge(e)?;
    }
    let mut end = 0;
    for subpath in &value.subpaths {
        charge(control, WorkKind::TokenVisit)?;
        let range = TableRange {
            first: subpath.first_edge,
            count: subpath.edge_count,
        };
        range.require(value.edges.len(), 0)?;
        if range.first < end {
            return Err(invalid(0));
        }
        end = range.end().ok_or_else(|| invalid(0))?;
    }
    for segment in &value.segments {
    for segment in &value.segments {
        charge(control, WorkKind::TokenVisit)?;
        segment_valid(source, *segment, value.edges.len(), value.numbers.len())?;
    }
    for number in &value.numbers {
        charge(control, WorkKind::SourceRead)?;
        span(source, number.source)?;
        if !number.value.is_finite() {
            return Err(invalid(number.source.start));
        }
    }
    Ok(())
}
fn segment_valid(
    source: &[u8],
    value: vexel_svg_path::PathSegment,
    edges: usize,
    numbers: usize,
) -> Result<()> {
    span(source, value.source)?;
    TableRange {
        first: value.first_edge,
        count: value.edge_count,
    }
    .require(edges, value.source.start)?;
    TableRange {
        first: value.first_number,
        count: value.number_count,
    }
    .require(numbers, value.source.start)?;
    let count = match value.command.to_ascii_uppercase() {
        b'M' | b'L' | b'T' => 2,
        b'H' | b'V' => 1,
        b'C' => 6,
        b'S' | b'Q' => 4,
        b'A' => 7,
        b'Z' => 0,
        _ => return Err(invalid(value.source.start)),
    };
    if value.number_count != count
        || (value.command.eq_ignore_ascii_case(&b'M') && value.edge_count != 0)
    {
        return Err(invalid(value.source.start));
    }
    if matches!(
        value.command.to_ascii_uppercase(),
        b'L' | b'H' | b'V' | b'Z'
    ) && value.edge_count > 1
    {
        return Err(invalid(value.source.start));
    }
    if let Some(offset) = value.command_offset {
        if offset < value.source.start
            || offset >= value.source.end
            || source.get(offset).map(u8::to_ascii_uppercase)
                != Some(value.command.to_ascii_uppercase())
        {
            return Err(invalid(offset));
        }
    }
    Ok(())
}
pub(crate) fn image(value: &Image, control: &mut dyn WorkControl) -> Result<()> {
    charge(control, WorkKind::Media)?;
    value.pixels.validate(0)?;
    if value.pixels.width > 16384
        || value.pixels.height > 16384
        || (value.pixels.width as usize) * (value.pixels.height as usize) > 67_108_864
    {
        return Err(limit(LimitKind::Images));
    }
    for row in value.pixels.rgba[..value.pixels.byte_count].chunks_exact(value.pixels.row_stride) {
        for pixel in row[..value.pixels.width as usize * 4].chunks_exact(4) {
            charge(control, WorkKind::Media)?;
            if pixel[..3].iter().any(|v| *v > pixel[3]) {
                return Err(invalid(0));
            }
        }
    }
    if ![
        value.x,
        value.y,
        value.width,
        value.height,
        value.draw_x,
        value.draw_y,
        value.draw_width,
        value.draw_height,
    ]
    .into_iter()
    .all(coord)
        || value.width <= 0.0
        || value.height <= 0.0
        || value.draw_width < 0.0
        || value.draw_height < 0.0
    {
        return Err(invalid(0));
    }
    Ok(())
}
pub(crate) fn clip(
    builder: &SceneBuilder,
    id: SceneId,
    value: &Clip,
    control: &mut dyn WorkControl,
) -> Result<()> {
    clip_view(builder.scene(id)?, value, control)
}
pub(crate) fn clip_view(
    scene: SceneView<'_>,
    value: &Clip,
    control: &mut dyn WorkControl,
) -> Result<()> {
    if !region(&value.bounds) || !affine_valid(value.user_inverse) {
        return Err(invalid(0));
    }
    if value.geometry.edges.len() > 65536 || value.geometry.shapes.len() > 64 {
        return Err(limit(LimitKind::Clips));
    }
    if let Some(node) = value.owner_node {
        if scene.transform(node).is_none() {
            return Err(invalid(0));
        }
    }
    let mut parent = value.parent;
    let mut depth = 1;
    while let Some(id) = parent {
        charge(control, WorkKind::ClipChain)?;
        let clip = scene.clip(id).ok_or_else(|| invalid(0))?;
        parent = clip.parent;
        depth += 1;
        if depth > 256 {
            return Err(limit(LimitKind::Clips));
        }
    }
    for &e in &value.geometry.edges {
        charge(control, WorkKind::ClipEdge)?;
        edge(e)?;
    }
    for child in &value.geometry.shapes {
        charge(control, WorkKind::ClipChild)?;
        child.edges.require(value.geometry.edges.len(), 0)?;
    }
    Ok(())
}
pub(crate) fn pattern(
    _builder: &SceneBuilder,
    _id: SceneId,
    value: &Pattern,
    control: &mut dyn WorkControl,
) -> Result<()> {
    charge(control, WorkKind::PaintVisit)?;
    if (value.tile.width() as usize) * (value.tile.height() as usize) > 1_048_576
        || value.tile.allocated_byte_count() > 16 * 1024 * 1024
    {
        return Err(limit(LimitKind::Patterns));
    }
    if !coord(value.tile_width)
        || !coord(value.tile_height)
        || value.tile_width <= 0.0
        || value.tile_height <= 0.0
        || !affine_valid(value.content_transform)
    {
        return Err(invalid(0));
    }
    Ok(())
}
pub(crate) fn mask(
    builder: &SceneBuilder,
    id: SceneId,
    value: &Mask,
    control: &mut dyn WorkControl,
) -> Result<()> {
    charge(control, WorkKind::ClipChild)?;
    let child = builder.index(value.content)?;
    if value.content == id
        || !builder.scenes[child].sealed
        || !region(&value.region)
        || !affine_valid(value.region_transform)
    {
        return Err(invalid(0));
    }
    source_offset(&builder.source, value.source_offset)
}
pub(crate) fn filter(
    value: Filter,
    primitives: &[FilterPrimitive],
    control: &mut dyn WorkControl,
) -> Result<()> {
    if primitives.len() > 16 {
        return Err(limit(LimitKind::Filters));
    }
    if !region(&value.region) {
        return Err(invalid(0));
    }
    for (index, p) in primitives.iter().enumerate() {
        charge(control, WorkKind::FilterPixel)?;
        if p.merge_count > 8 || !finite(&p.values) {
            return Err(invalid(p.source_offset));
        }
        for input in [p.input, p.input2]
            .into_iter()
            .chain(p.merge_inputs[..p.merge_count as usize].iter().copied())
        {
            if let FilterInput::Result(result) = input {
                if result >= index {
                    return Err(invalid(p.source_offset));
                }
            }
        }
        let mode_cap = match p.kind {
            FilterKind::Blend => 4,
            FilterKind::Composite => 6,
            FilterKind::ColorMatrix => 3,
            _ => 0,
        };
        if p.mode > mode_cap {
            return Err(invalid(p.source_offset));
        }
        if matches!(p.kind, FilterKind::Offset | FilterKind::DropShadow)
            && (p.values[2].abs() > 4096.0 || p.values[3].abs() > 4096.0)
        {
            return Err(invalid(p.source_offset));
        }
        if p.kind == FilterKind::ColorMatrix && p.mode == 1 && !(0.0..=1.0).contains(&p.values[0]) {
            return Err(invalid(p.source_offset));
        }
        if matches!(p.kind, FilterKind::GaussianBlur | FilterKind::DropShadow)
            && (!(0.0..=32.0).contains(&p.values[0]) || !(0.0..=32.0).contains(&p.values[1]))
        {
            return Err(invalid(p.source_offset));
        }
    }
    Ok(())
}
pub(crate) fn group(
    builder: &SceneBuilder,
    id: SceneId,
    value: &OpacityGroup,
    index: usize,
    control: &mut dyn WorkControl,
) -> Result<()> {
    let scene = builder.scene(id)?;
    value.shapes.require(scene.shapes.len(), 0)?;
    if !value.opacity.is_finite() || !(0.0..=1.0).contains(&value.opacity) || value.blend_mode > 4 {
        return Err(invalid(0));
    }
    if let Some(filter) = value.filter {
        if scene.filter(filter).is_none() {
            return Err(invalid(0));
        }
    }
    if let Some(mask) = value.mask {
        if scene.mask(mask).is_none() {
            return Err(invalid(0));
        }
    }
    let mut parent = value.parent;
    let mut depth = 1;
    while let Some(id) = parent {
        charge(control, WorkKind::ClipChain)?;
        let group = scene.group(id).ok_or_else(|| invalid(0))?;
        if value.shapes.first < group.shapes.first || value.shapes.end() > group.shapes.end() {
            return Err(invalid(0));
        }
        parent = group.parent;
        depth += 1;
        if depth > 64 {
            return Err(limit(LimitKind::Depth));
        }
    }
